definition.script:
pipeline {
    agent any

    stages {

        stage('Checkout') {
            steps {
                git branch: 'main', url: 'https://github.com/jiku23ainds-cloud/hello-maven.git'
            }
        }

        stage('Build') {
            steps {
                dir('hello-maven/MyMavenApp') {   // ✅ CORRECT PATH
                    sh 'mvn clean package'
                }
            }
        }

        stage('Test') {
            steps {
                dir('hello-maven/MyMavenApp') {   // ✅ CORRECT PATH
                    sh 'mvn test'
                }
            }
        }
    }
}
